using System;
using System.Drawing;
using System.IO;
using System.IO.Compression;
using System.Net;
using System.Linq;
using System.Collections.Generic;
using System.Windows.Forms;
using Microsoft.Win32;
class Release { public string tag,url; }
class ModInstaller : Form {
public string GamePath {get{return path.Text;}} TextBox path=new TextBox(); string[] detected=new string[0]; public Action<string> StatusChanged; public Action<bool> BusyChanged;
public Dictionary<string,string> Platforms=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);
public string SelectedPlatform {get{string source;return Platforms.TryGetValue(GamePath,out source)?source:"PC";}}
void AddRoot(HashSet<string> roots,string candidate,string source){string p=Path.GetFullPath(candidate).TrimEnd(Path.DirectorySeparatorChar);roots.Add(p);Platforms[p]=source;}
public string[] AvailablePlatforms {get{return detected.Select(p=>Platforms.ContainsKey(p)?Platforms[p]:"PC").Distinct().ToArray();}}
public void SelectPlatform(string source){string selected=detected.FirstOrDefault(p=>Platforms.ContainsKey(p)&&Platforms[p]==source);if(selected!=null)path.Text=selected;}
public static string CheckBepInEx(string root){string[] required={"winhttp.dll","doorstop_config.ini","BepInEx/core/BepInEx.dll","BepInEx/core/BepInEx.Preloader.dll"};int present=required.Count(p=>File.Exists(Path.Combine(root,p)));if(present==0)return "Non installé";if(present!=required.Length||required.Any(p=>new FileInfo(Path.Combine(root,p)).Length==0))return "À réparer";string ini=File.ReadAllText(Path.Combine(root,"doorstop_config.ini"));if(System.Text.RegularExpressions.Regex.IsMatch(ini,@"(?im)^\s*enabled\s*=\s*false\s*$"))return "Désactivé";return "Installé";}
void Say(string text){if(StatusChanged!=null)StatusChanged(text);}
static bool Valid(string root){return File.Exists(Path.Combine(root,"Gorilla Tag.exe"))&&Directory.Exists(Path.Combine(root,"Gorilla Tag_Data"));}
 public bool ChooseGame(){if(Valid(path.Text))return true;if(detected.Length==1){path.Text=detected[0];return true;}if(detected.Length>1){using(var dialog=new Form{Text="Choisir le jeu",ClientSize=new Size(540,145),StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,BackColor=BackColor,ForeColor=ForeColor,Font=Font}){var list=new ComboBox{Left=16,Top=25,Width=508,DropDownStyle=ComboBoxStyle.DropDownList};foreach(string p in detected)list.Items.Add(p);list.SelectedIndex=0;dialog.Controls.Add(list);var ok=new Button{Text="Choisir",Left=364,Top=80,Width=160,Height=36,DialogResult=DialogResult.OK};dialog.Controls.Add(ok);dialog.AcceptButton=ok;if(dialog.ShowDialog(this)!=DialogResult.OK)return false;path.Text=(string)list.SelectedItem;return true;}}using(var picker=new System.Windows.Forms.OpenFileDialog{Filter="Gorilla Tag|Gorilla Tag.exe",Title="Où est installé Gorilla Tag ?"}){if(picker.ShowDialog(this)!=DialogResult.OK)return false;string selected=Path.GetDirectoryName(picker.FileName);if(!Valid(selected)){Say("Ce dossier ne contient pas Gorilla Tag.");return false;}path.Text=selected;detected=new[]{selected};Platforms[selected]=selected.IndexOf("steamapps",StringComparison.OrdinalIgnoreCase)>=0?"Steam":"Meta";return true;}}
 public void OpenFolder(string relative){if(!Valid(path.Text))throw new Exception("Sélectionne le dossier contenant Gorilla Tag.exe et Gorilla Tag_Data.");string p=Path.Combine(path.Text,relative);Directory.CreateDirectory(p);System.Diagnostics.Process.Start("explorer.exe","\""+p+"\"");}
 public void Detect(){Platforms.Clear();var roots=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var steam=new List<string>();using(var k=Registry.CurrentUser.OpenSubKey(@"Software\Valve\Steam")){if(k!=null&&k.GetValue("SteamPath")!=null)steam.Add(k.GetValue("SteamPath").ToString());}steam.Add(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),"Steam"));foreach(var s in steam.ToArray()){string v=Path.Combine(s,"steamapps","libraryfolders.vdf");if(File.Exists(v))foreach(System.Text.RegularExpressions.Match m in System.Text.RegularExpressions.Regex.Matches(File.ReadAllText(v),"\"path\"\\s*\"([^\"]+)\""))steam.Add(m.Groups[1].Value.Replace("\\\\","\\"));}foreach(var s in steam)AddRoot(roots,Path.Combine(s,"steamapps","common","Gorilla Tag"),"Steam");
 var meta=new List<string>{Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"Oculus","Software"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),"Oculus","Software")};using(var k=Registry.CurrentUser.OpenSubKey(@"Software\Oculus VR, LLC\Oculus\Libraries")){if(k!=null)foreach(string name in k.GetSubKeyNames())using(var sub=k.OpenSubKey(name)){var p=sub.GetValue("Path");if(p!=null)meta.Add(p.ToString());}}
 foreach(string s in meta){AddRoot(roots,Path.Combine(s,"Software","another-axiom-gorilla-tag"),"Meta");AddRoot(roots,Path.Combine(s,"another-axiom-gorilla-tag"),"Meta");string d=Path.Combine(s,"Software");if(Directory.Exists(d))foreach(string child in Directory.GetDirectories(d))AddRoot(roots,child,"Meta");}var found=roots.Where(Valid).Select(p=>Path.GetFullPath(p).TrimEnd(Path.DirectorySeparatorChar)).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();detected=found;if(found.Length>0){path.Text=found[0];Say("Jeu détecté : "+path.Text);if(found.Length>1)Say("Plusieurs installations détectées. Parcourir permet d'en choisir une autre.");Say("Gorilla Tag détecté.");}else Say("Sélection du jeu au premier clic.");}
 static WebClient Client(){ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;var c=new WebClient();c.Headers[HttpRequestHeader.UserAgent]="GorillaTagModInstaller/1.0";return c;}
 void Busy(bool value){if(BusyChanged!=null)BusyChanged(value);}
 public static bool Allowed(string p){p=p.Replace('\\','/');return p.StartsWith("BepInEx/core/",StringComparison.OrdinalIgnoreCase)||p.Equals("winhttp.dll",StringComparison.OrdinalIgnoreCase)||p.Equals("doorstop_config.ini",StringComparison.OrdinalIgnoreCase)||p.Equals(".doorstop_version",StringComparison.OrdinalIgnoreCase);}
 public async void Install(){Busy(true);string temp=null;try{string root=Path.GetFullPath(path.Text);if(!Valid(root))throw new Exception("Dossier du jeu invalide.");if(System.Diagnostics.Process.GetProcessesByName("Gorilla Tag").Length>0)throw new Exception("Ferme Gorilla Tag avant l'installation.");if(File.Exists(Path.Combine(root,"GameAssembly.dll"))||!Directory.Exists(Path.Combine(root,"Gorilla Tag_Data","Managed")))throw new Exception("Cette installation n'est pas identifiée comme Unity Mono. Installation BepInEx 5 interrompue.");var r=new Release{tag="v5.4.23.5",url="https://github.com/BepInEx/BepInEx/releases/download/v5.4.23.5/BepInEx_win_x64_5.4.23.5.zip"};if(r==null||r.url==null||!r.tag.StartsWith("v5."))throw new Exception("Choisis une version BepInEx 5 Windows x64. Les autres versions restent affichées pour information.");
 temp=Path.Combine(Path.GetTempPath(),"GorillaTagInstaller-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);string zip=Path.Combine(temp,"bepinex.zip");Say("Téléchargement de "+r.tag+"…");using(var c=Client())await c.DownloadFileTaskAsync(new Uri(r.url),zip);
 var files=new Dictionary<string,byte[]>();using(var archive=ZipFile.OpenRead(zip)){foreach(var entry in archive.Entries){if(!Allowed(entry.FullName)||entry.FullName.EndsWith("/"))continue;string dest=Path.GetFullPath(Path.Combine(root,entry.FullName));if(!dest.StartsWith(root.TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase))throw new Exception("Archive invalide.");using(var ms=new MemoryStream()){using(var stream=entry.Open())stream.CopyTo(ms);files[entry.FullName]=ms.ToArray();}}}if(!files.ContainsKey("winhttp.dll")||!files.ContainsKey("doorstop_config.ini")||!files.Keys.Any(f=>f.EndsWith("BepInEx.dll",StringComparison.OrdinalIgnoreCase)))throw new Exception("Archive BepInEx incomplète.");
 string backup=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"GorillaTagModInstaller","Backups",DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,6));Directory.CreateDirectory(backup);foreach(string dir in new[]{"BepInEx\\plugins","BepInEx\\config"}){string src=Path.Combine(root,dir);if(Directory.Exists(src))foreach(string f in Directory.GetFiles(src,"*",SearchOption.AllDirectories)){string target=Path.Combine(backup,f.Substring(root.TrimEnd('\\').Length+1));Directory.CreateDirectory(Path.GetDirectoryName(target));File.Copy(f,target,true);}}
 var changed=new List<string>();try{foreach(var f in files){string dest=Path.Combine(root,f.Key);if(File.Exists(dest)){string old=Path.Combine(backup,"loader",f.Key);Directory.CreateDirectory(Path.GetDirectoryName(old));File.Copy(dest,old,true);}changed.Add(f.Key);Directory.CreateDirectory(Path.GetDirectoryName(dest));File.WriteAllBytes(dest,f.Value);}}catch{foreach(string f in changed){string old=Path.Combine(backup,"loader",f),dest=Path.Combine(root,f);if(File.Exists(old))File.Copy(old,dest,true);else if(File.Exists(dest))File.Delete(dest);}throw;}
 Directory.CreateDirectory(Path.Combine(root,"BepInEx","plugins"));Directory.CreateDirectory(Path.Combine(root,"BepInEx","config"));Say("BepInEx "+r.tag+" installé / réparé. Plugins et configurations conservés.");Say("Sauvegarde : "+backup);Say("La réparation concerne BepInEx ; elle ne corrige pas les plugins défectueux ni les fichiers du jeu.");Say("BepInEx installé. Tes mods sont conservés.");
 }catch(Exception ex){Say("Échec : "+ex.Message);}finally{if(temp!=null&&Directory.Exists(temp))Directory.Delete(temp,true);Busy(false);}}

}